1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x1, y1]: Cell, [x2, y2]: Cell): boolean => x1 === x2 && y1 === y2;
4	
5	const chebyshevDistance = ([x1, y1]: Cell, [x2, y2]: Cell): number =>
6	  Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
7	
8	const isNeighbor = (cell: Cell, otherCell: Cell): boolean =>
9	  chebyshevDistance(cell, otherCell) === 1;
10	
11	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
12	  liveCells.filter((otherCell) => isNeighbor(cell, otherCell)).length;
13	
14	const survives = (cell: Cell, liveCells: Cell[]): boolean => {
15	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
16	  return liveNeighbors === 2 || liveNeighbors === 3;
17	};
18	
19	const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
20	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
21	
22	const neighborsOf = ([x, y]: Cell): Cell[] => [
23	  [x - 1, y - 1],
24	  [x, y - 1],
25	  [x + 1, y - 1],
26	  [x - 1, y],
27	  [x + 1, y],
28	  [x - 1, y + 1],
29	  [x, y + 1],
30	  [x + 1, y + 1],
31	];
32	
33	const candidateCells = (liveCells: Cell[]): Cell[] => {
34	  const liveCellsAndNeighbors = [...liveCells, ...liveCells.flatMap(neighborsOf)];
35	  return liveCellsAndNeighbors.filter(
36	    (cell, index) =>
37	      liveCellsAndNeighbors.findIndex((other) => isSameCell(cell, other)) === index,
38	  );
39	};
40	
41	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
42	  candidateCells(liveCells).filter((cell) =>
43	    isLive(cell, liveCells)
44	      ? survives(cell, liveCells)
45	      : countLiveNeighbors(cell, liveCells) === 3,
46	  );
