1	import { describe, it, expect } from "vitest";
2	import { type Cell, nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return an empty result for an empty grid", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should let a single live cell die from underpopulation", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("should let two adjacent live cells die from underpopulation", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 1],
15	        [1, 1],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("should let a live cell with 2 live neighbors survive", () => {
20	    expect(
21	      nextGeneration([
22	        [0, 0],
23	        [1, 0],
24	        [0, 1],
25	      ]),
26	    ).toContainEqual([0, 0]);
27	  });
28	  it("should let a live cell with 3 live neighbors survive", () => {
29	    expect(
30	      nextGeneration([
31	        [0, 0],
32	        [1, 0],
33	        [0, 1],
34	        [1, 1],
35	      ]),
36	    ).toContainEqual([0, 0]);
37	  });
38	  it("should let a live cell with 4 live neighbors die from overpopulation", () => {
39	    expect(
40	      nextGeneration([
41	        [1, 1],
42	        [0, 0],
43	        [1, 0],
44	        [2, 0],
45	        [0, 1],
46	      ]),
47	    ).not.toContainEqual([1, 1]);
48	  });
49	  it("should bring a dead cell with exactly 3 live neighbors to life", () => {
50	    expect(
51	      nextGeneration([
52	        [0, 0],
53	        [1, 0],
54	        [0, 1],
55	      ]),
56	    ).toContainEqual([1, 1]);
57	  });
58	  it("should keep a block still life unchanged", () => {
59	    const block: Cell[] = [
60	      [0, 0],
61	      [1, 0],
62	      [0, 1],
63	      [1, 1],
64	    ];
65	    const result = nextGeneration(block);
66	    expect(result).toHaveLength(4);
67	    expect(result).toEqual(expect.arrayContaining(block));
68	  });
69	  it.todo("should turn a vertical blinker into a horizontal blinker");
70	  it.todo("should turn a horizontal blinker back into a vertical blinker");
71	  it.todo("should apply the rules to cells at negative coordinates");
72	});
